import exact,random,copy,json
# dense small fabric with many equal paths
prof={'groups':2,'jitter_ps':[0,0],'measurements':[[0,1,0,0]]}
f={'n':3,'interval_ns':1,'slice_ns':100,'offset_ns':0,'drift_ppb':[0,0,0],'heat':[],'anchors':[[0,0,4]],'links':[
 {'ends':[[0,0,0],[1,0,1]],'delay_ns':[1,1],'defer_rounds':[0,0]},
 {'ends':[[0,1,0],[2,1,1]],'delay_ns':[1,1],'defer_rounds':[0,0]},
 {'ends':[[1,2,1],[2,2,1]],'delay_ns':[1,1],'defer_rounds':[0,0]},
],'slices':[[0,1,2]],'blackouts':[],'guards_ns':[0],'reconfig_ns':0}
cal=exact.solve_calibration(prof);fab=exact.Fabric(f);art=exact.make_plan_artifact(fab,cal);print('base audit',exact.audit_plan(prof,f,art),'warm',art['warmup_cycle'])
b=art['bounds_as'];a=art['age_rounds'];pr=art['pred'];msg=fab.message_adjacency(cal,0)
for trial in range(200):
 alt=copy.deepcopy(art)
 for _ in range(random.randint(1,5)):
  p=random.randrange(fab.P);i=random.randrange(fab.n)
  if alt['pred'][p][i] is None:continue
  # collect any valid step from finite cell
  opts=[]
  for pv2 in range(fab.V):
   pp=pv2//fab.n;ii=pv2%fab.n
   if b[pp][ii] is None:continue
   if ii==i and (pp+1)%fab.P==p:
    cb=fab.eff[pv2]*fab.T
    if b[p][i]==b[pp][ii]+cb and a[p][i]==a[pp][ii]+1:opts.append([pv2,-1])
   for e in msg[pv2]:
    if e[2]<art['guard_ns']:continue
    dv=e[0];q=dv//fab.n;ij=dv%fab.n
    if q==p and ij==i:
     cb=e[1]//fab.base;ca=e[1]%fab.base
     if b[p][i]==b[pp][ii]+cb and a[p][i]==a[pp][ii]+ca:opts.append([pv2,e[3]])
  if opts:alt['pred'][p][i]=random.choice(opts)
 if not exact.audit_plan(prof,f,alt):
  print('ALT REJECT',trial,json.dumps(alt['pred']));break
else:print('200 alternative pred variants accepted')
PY
